CREATE TYPE "BookingStatus" AS ENUM ('CONFIRMED', 'COMPLETED', 'CANCELLED', 'NO_SHOW');
ALTER TABLE "Barbershop" ADD COLUMN "ownerId" TEXT, ADD COLUMN "phone" TEXT NOT NULL DEFAULT '', ADD COLUMN "description" TEXT NOT NULL DEFAULT '', ADD COLUMN "timezone" TEXT NOT NULL DEFAULT 'America/Sao_Paulo', ADD COLUMN "openingMinute" INTEGER NOT NULL DEFAULT 540, ADD COLUMN "closingMinute" INTEGER NOT NULL DEFAULT 1260, ADD COLUMN "workingDays" INTEGER[] DEFAULT ARRAY[1,2,3,4,5,6]::INTEGER[], ADD COLUMN "minimumNoticeMinutes" INTEGER NOT NULL DEFAULT 60, ADD COLUMN "bookingHorizonDays" INTEGER NOT NULL DEFAULT 60, ADD COLUMN "cancellationNoticeMinutes" INTEGER NOT NULL DEFAULT 120, ADD COLUMN "active" BOOLEAN NOT NULL DEFAULT true;
ALTER TABLE "Barbershop" ADD CONSTRAINT "Barbershop_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Service" ADD COLUMN "durationMinutes" INTEGER NOT NULL DEFAULT 45, ADD COLUMN "active" BOOLEAN NOT NULL DEFAULT true;
CREATE TABLE "Staff" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true, "barbershopId" TEXT NOT NULL REFERENCES "Barbershop"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
INSERT INTO "Staff" ("id", "name", "barbershopId") SELECT 'legacy-' || "id", 'Equipe principal', "id" FROM "Barbershop";
ALTER TABLE "Booking" ADD COLUMN "endDate" TIMESTAMP(3), ADD COLUMN "status" "BookingStatus" NOT NULL DEFAULT 'CONFIRMED', ADD COLUMN "price" DECIMAL(10,2), ADD COLUMN "serviceName" TEXT, ADD COLUMN "staffId" TEXT, ADD COLUMN "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, ADD COLUMN "cancelledAt" TIMESTAMP(3);
UPDATE "Booking" b SET "endDate" = b."date" + INTERVAL '45 minutes', "price" = s."price", "serviceName" = s."name", "staffId" = 'legacy-' || b."barbershopId" FROM "Service" s WHERE s."id" = b."serviceId";
ALTER TABLE "Booking" ALTER COLUMN "endDate" SET NOT NULL, ALTER COLUMN "price" SET NOT NULL, ALTER COLUMN "serviceName" SET NOT NULL, ALTER COLUMN "staffId" SET NOT NULL;
ALTER TABLE "Booking" ADD CONSTRAINT "Booking_staffId_fkey" FOREIGN KEY ("staffId") REFERENCES "Staff"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "ScheduleBlock" ("id" TEXT NOT NULL PRIMARY KEY, "staffId" TEXT NOT NULL REFERENCES "Staff"("id") ON DELETE RESTRICT ON UPDATE CASCADE, "start" TIMESTAMP(3) NOT NULL, "end" TIMESTAMP(3) NOT NULL, "reason" TEXT NOT NULL DEFAULT 'Indisponível', CONSTRAINT "ScheduleBlock_valid_interval" CHECK ("end" > "start"));
CREATE TABLE "EmailDelivery" ("id" TEXT NOT NULL PRIMARY KEY, "eventKey" TEXT NOT NULL UNIQUE, "recipient" TEXT NOT NULL, "subject" TEXT NOT NULL, "body" TEXT NOT NULL, "state" TEXT NOT NULL DEFAULT 'PENDING', "attempts" INTEGER NOT NULL DEFAULT 0, "lastAttemptAt" TIMESTAMP(3), "lastError" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "sentAt" TIMESTAMP(3));
CREATE INDEX "Booking_barbershopId_date_idx" ON "Booking"("barbershopId", "date");
CREATE INDEX "Booking_staffId_date_endDate_idx" ON "Booking"("staffId", "date", "endDate");
CREATE INDEX "Booking_userId_date_idx" ON "Booking"("userId", "date");
CREATE INDEX "Staff_barbershopId_idx" ON "Staff"("barbershopId");
CREATE INDEX "ScheduleBlock_staffId_start_end_idx" ON "ScheduleBlock"("staffId", "start", "end");
ALTER TABLE "Booking" ADD CONSTRAINT "Booking_valid_interval" CHECK ("endDate" > "date");
ALTER TABLE "Service" ADD CONSTRAINT "Service_valid_values" CHECK ("price" >= 0 AND "durationMinutes" BETWEEN 15 AND 480);
